/// Build-time SF Symbol → Lucide catalog.
///
/// This file intentionally contains no browser runtime implementation and no legacy
/// JavaScript bridge dependency. The Bun asset generator reads this canonical
/// catalog and emits only reachable icons for the BrowserIO runtime.
enum SwiftUIWebLucideCatalog {
  private static func iconName(for symbol: String) -> String? {
