    // Common actions.
    case "checkmark": return "check"
    case "checkmark.circle", "checkmark.circle.fill": return "circle-check"
    case "checkmark.square", "checkmark.square.fill": return "square-check"
    case "xmark", "multiply": return "x"
    case "xmark.circle", "xmark.circle.fill": return "circle-x"
    case "xmark.square", "xmark.square.fill": return "square-x"
    case "plus": return "plus"
    case "plus.circle", "plus.circle.fill": return "circle-plus"
    case "plus.square", "plus.square.fill": return "square-plus"
    case "minus": return "minus"
    case "minus.circle", "minus.circle.fill": return "circle-minus"
    case "minus.square", "minus.square.fill": return "square-minus"
    case "ellipsis", "ellipsis.horizontal": return "ellipsis"
