    case "slider.horizontal.3", "slider.horizontal.3.circle", "slider.horizontal.3.circle.fill": return "sliders-horizontal"
    case "line.3.horizontal.decrease", "line.3.horizontal.decrease.circle": return "filter"
    case "arrow.clockwise", "arrow.clockwise.circle", "arrow.clockwise.circle.fill": return "rotate-cw"
    case "arrow.counterclockwise", "arrow.counterclockwise.circle", "arrow.counterclockwise.circle.fill": return "rotate-ccw"
    case "arrow.uturn.backward", "arrow.uturn.backward.circle", "arrow.uturn.backward.circle.fill": return "undo-2"
    case "arrow.uturn.forward", "arrow.uturn.forward.circle", "arrow.uturn.forward.circle.fill": return "redo-2"

    // Directional controls.
    case "chevron.left": return "chevron-left"
    case "chevron.right": return "chevron-right"
    case "chevron.up": return "chevron-up"
    case "chevron.down": return "chevron-down"
    case "chevron.left.circle", "chevron.left.circle.fill": return "circle-chevron-left"
    case "chevron.right.circle", "chevron.right.circle.fill": return "circle-chevron-right"
    case "chevron.up.circle", "chevron.up.circle.fill": return "circle-chevron-up"
    case "chevron.down.circle", "chevron.down.circle.fill": return "circle-chevron-down"
    case "arrow.left": return "arrow-left"
    case "arrow.right": return "arrow-right"
    case "arrow.up": return "arrow-up"
    case "arrow.down": return "arrow-down"
    case "arrow.left.circle", "arrow.left.circle.fill": return "circle-arrow-left"
    case "arrow.right.circle", "arrow.right.circle.fill": return "circle-arrow-right"
    case "arrow.up.circle", "arrow.up.circle.fill": return "circle-arrow-up"
    case "arrow.down.circle", "arrow.down.circle.fill": return "circle-arrow-down"
    case "arrow.left.and.right": return "arrow-left-right"
    case "arrow.up.and.down": return "arrow-up-down"

    // Navigation and settings.
    case "gearshape", "gearshape.fill", "gear", "gear.fill", "gearshape.circle", "gearshape.circle.fill": return "settings"
    case "house", "house.fill", "house.circle", "house.circle.fill": return "home"
    case "sidebar.left", "sidebar.right", "sidebar.leading", "sidebar.trailing": return "panel-left"
    case "rectangle.split.3x1", "rectangle.split.3x1.fill": return "columns-3"
    case "rectangle.split.2x1", "rectangle.split.2x1.fill": return "columns-2"
    case "rectangle.stack", "rectangle.stack.fill": return "layers"
    case "magnifyingglass", "magnifyingglass.circle", "magnifyingglass.circle.fill": return "search"
    case "link", "link.circle", "link.circle.fill": return "link"
    case "square.and.arrow.up", "square.and.arrow.up.fill": return "upload"
