    case "questionmark.circle", "questionmark.circle.fill": return "circle-help"
    case "info.circle", "info.circle.fill": return "info"
    case "exclamationmark.triangle", "exclamationmark.triangle.fill": return "triangle-alert"
    case "exclamationmark.circle", "exclamationmark.circle.fill": return "circle-alert"

    // Content and editing.
    case "trash", "trash.fill", "trash.circle", "trash.circle.fill": return "trash-2"
    case "pencil", "pencil.circle", "pencil.circle.fill": return "pencil"
    case "square.and.pencil", "square.and.pencil.circle", "square.and.pencil.circle.fill": return "square-pen"
    case "doc", "doc.fill", "doc.text", "doc.text.fill", "note.text", "note.text.fill": return "file-text"
    case "doc.badge.plus", "doc.badge.plus.fill": return "file-plus-2"
    case "folder", "folder.fill", "folder.circle", "folder.circle.fill": return "folder"
    case "book", "book.fill", "book.pages", "book.pages.fill": return "book-open"
    case "books.vertical", "books.vertical.fill", "text.book.closed", "book.closed": return "book"
    case "bookmark", "bookmark.fill", "bookmark.circle", "bookmark.circle.fill": return "bookmark"
    case "tag", "tag.fill": return "tag"
    case "paperclip", "paperclip.circle", "paperclip.circle.fill": return "paperclip"
    case "clipboard", "clipboard.fill": return "clipboard"
    case "square", "square.fill": return "square"
    case "circle", "circle.fill": return "circle"
    case "rectangle", "rectangle.fill": return "rectangle-horizontal"

    case "tray", "tray.fill": return "inbox"
    case "creditcard", "creditcard.fill": return "credit-card"
    case "chart.bar", "chart.bar.fill", "chart.bar.xaxis": return "chart-column"
    case "chart.line.uptrend.xyaxis", "chart.line.uptrend.xyaxis.circle", "chart.line.uptrend.xyaxis.circle.fill": return "trending-up"
    case "waveform.path", "waveform.path.ecg", "waveform.path.ecg.rectangle", "waveform.path.ecg.rectangle.fill": return "activity"

    // Dates, places, commerce and devices.
    case "calendar", "calendar.circle", "calendar.circle.fill", "calendar.badge.plus": return "calendar"
    case "clock", "clock.fill": return "clock"
    case "clock.arrow.circlepath", "clock.arrow.trianglehead.counterclockwise.rotate.90": return "history"
    case "mappin", "mappin.and.ellipse", "mappin.circle", "mappin.circle.fill", "location", "location.fill": return "map-pin"
    case "map", "map.fill": return "map"
    case "cart", "cart.fill", "cart.circle", "cart.circle.fill": return "shopping-cart"
    case "bag", "bag.fill", "bag.circle", "bag.circle.fill": return "shopping-bag"
    case "globe", "globe.americas", "globe.europe.africa": return "globe"
    case "wifi", "wifi.circle", "wifi.circle.fill": return "wifi"
    case "lock", "lock.fill", "lock.circle", "lock.circle.fill": return "lock"
    case "checkmark.shield", "checkmark.shield.fill", "lock.shield", "lock.shield.fill": return "shield-check"
    case "iphone", "iphone.gen1", "iphone.gen2", "iphone.gen3", "rectangle.portrait", "rectangle.portrait.fill": return "smartphone"
    case "cpu", "cpu.fill": return "cpu"
    case "dollarsign.circle", "dollarsign.circle.fill", "brazilianrealsign.circle", "brazilianrealsign.circle.fill", "centsign.circle", "centsign.circle.fill": return "coins"
    case "key", "key.fill": return "key-round"
    case "eye", "eye.fill": return "eye"
    case "eye.slash", "eye.slash.fill": return "eye-off"
    case "camera", "camera.fill": return "camera"
    case "photo", "photo.fill", "photo.on.rectangle", "photo.on.rectangle.fill": return "image"
    case "square.and.arrow.up.on.square", "square.and.arrow.up.on.square.fill": return "share-2"

    // Media and appearance.
    case "play", "play.fill": return "play"
    case "speaker.wave.2", "speaker.wave.2.fill": return "volume-2"
    case "captions.bubble", "captions.bubble.fill": return "captions"
    case "gauge.with.dots.needle.67percent", "gauge.with.dots.needle.50percent", "gauge.with.dots.needle.33percent": return "gauge"
