    case "arrow.2.squarepath": return "repeat-2"
    case "pin", "pin.fill": return "pin"
    case "selection.pin.in.out": return "map-pin"
    case "safari", "safari.fill": return "compass"
    case "at": return "at-sign"
    case "number": return "hash"
    case "tray.full", "tray.full.fill": return "inbox"
    case "person.crop.circle.badge.xmark": return "user-x"
    case "exclamationmark.bubble", "exclamationmark.bubble.fill": return "message-square-warning"
    case "dot.radiowaves.right", "badge.plus.radiowaves.right": return "radio"
    case "heart", "heart.fill": return "heart"
    case "sparkles", "wand.and.stars": return "sparkles"
    case "sun.max", "sun.max.fill": return "sun"
    case "moon", "moon.fill": return "moon"
    case "paintpalette", "paintpalette.fill": return "palette"
    case "paintbrush", "paintbrush.fill", "paintbrush.pointed", "paintbrush.pointed.fill": return "paintbrush"
    case "shield", "shield.fill": return "shield"
    case "calendar.badge.clock": return "calendar-clock"
    case "calendar.badge.exclamationmark": return "calendar-x"
    case "chevron.up.chevron.down": return "chevrons-up-down"
    case "lightbulb", "lightbulb.fill", "lightbulb.max", "lightbulb.max.fill": return "lightbulb"
    case "headphones", "headphones.circle", "headphones.circle.fill": return "headphones"
    case "film", "film.fill", "film.stack", "film.stack.fill": return "film"
    // Food Truck and similar apps.
    case "box.truck", "box.truck.fill", "truck.box", "truck.box.fill": return "truck"
    case "building.2", "building.2.fill", "building.2.crop.circle", "building.2.crop.circle.fill": return "building-2"
    case "chevron.forward": return "chevron-right"
    case "chevron.backward": return "chevron-left"
    case "cloud.sun", "cloud.sun.fill": return "cloud-sun"
    case "face.smiling", "face.smiling.fill": return "smile"
    case "fork.knife", "fork.knife.circle", "fork.knife.circle.fill": return "utensils"
    case "list.bullet.below.rectangle": return "list"
    case "person.badge.key", "person.badge.key.fill": return "key-round"
    case "plus.bubble", "plus.bubble.fill": return "message-square-plus"
    case "shippingbox", "shippingbox.fill": return "package"
    case "text.bubble", "text.bubble.fill": return "message-square-text"
    case "textformat": return "type"
    case "textformat.size": return "type"
    case "flame", "flame.fill": return "flame"
    case "briefcase", "briefcase.fill": return "briefcase"
    case "chevron.left.forwardslash.chevron.right": return "code"
    case "trophy", "trophy.fill", "trophy.circle", "trophy.circle.fill": return "trophy"
    case "arrowtriangle.right.and.line.vertical.and.arrowtriangle.left", "arrowtriangle.right.and.line.vertical.and.arrowtriangle.left.fill": return "arrow-left-right"

    default:
      // Many SF families only differ by a rendering variant.  When an exact
      // variant was not listed above, retry its base name before falling back
      // to the visible Core glyph.  This handles e.g. `folder.badge.plus`
      // without making unrelated symbols look misleading.
      if symbol.hasSuffix(".fill") { return iconName(for: String(symbol.dropLast(5))) }
      if symbol.hasSuffix(".circle") { return iconName(for: String(symbol.dropLast(7))) }
      if symbol.hasSuffix(".square") { return iconName(for: String(symbol.dropLast(7))) }
      if symbol.hasSuffix(".slash") { return iconName(for: String(symbol.dropLast(6))) }
      return nil
    }
